        d2betapardB2, d2betapardrdB, d2betapardRdB,d2betapardrdR,~,... %d2betapardR2 not used
		d3betapardrdB2,d3betapardB3,d3betapardBdR2,d3betapardB2dR,d3betapardrdRdB] = equation_of_state(kinetic_profiles,r,RR,BB);
    Ntheta = numel(omega);
    mF   = [0,1,2:(Ns+1)];
    rowsF = [1,2,(2 + Nb + (2:(Ns+1)))];
    mB   = 0:(Nb-1);
    rowsB = 3 + (1:Nb); 
    nmF = numel(mF);
    nmB = numel(mB);
	
	temp14 = ((BB - dbetapardB.*epsilon.^2).^2.*RR.^3);
	temp11 = epsilon.^2.*Pp.*cos(omega).*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - epsilon.^2.*P.*sin(omega).*sum(cos((-1 + ms).*omega).*Sp,3);
	Tfun = 1 - dbetapardB0.*epsilon.^2 + epsilon.^2.*t2;
	temp9 = deltap.*epsilon.*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - cos(omega).*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3);
	temp8 = sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(sin((-1 + ms).*omega).*Sp,3);
	temp7 = epsilon.^2.*P.*sin(omega) + r.*sin(omega) - epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3);
	temp6 = epsilon.^2.*Pp.*cos(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3);
	temp5 = cos(omega) + epsilon.^2.*Pp.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3);
	temp4 = deltap.*epsilon.^2.*P.*sin(omega) + deltap.*r.*sin(omega) - cos(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3);
	temp3 = epsilon.^2.*P.*cos(omega) + r.*cos(omega) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3);
	temp2 = -(deltap.*epsilon) + cos(omega) + epsilon.^2.*Pp.*cos(omega) + epsilon.*sum(cos((-1 + ms).*omega).*Sp,3);
	T8 = deltap.*epsilon.^2.*P.*cos(omega) + deltap.*r.*cos(omega) - sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - epsilon.^2.*Pp.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - sin(omega).*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - epsilon.^2.*Pp.*sin(omega).*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3) - epsilon.^2.*P.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - r.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) + sum(-((-1 + ms).^2.*cos((-1 + ms).*omega).*S),3).*(temp2) - epsilon.^2.*P.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) - r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) - sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(temp5) + epsilon.^2.*P.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3) + r.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3).*sum(sin((-1 + ms).*omega).*Sp,3) - epsilon.^2.*P.*sin(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3) - r.*sin(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3) + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3);

    temp1 = r + epsilon.^2.*Pp.*r - deltap.*epsilon.*r.*cos(omega) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) - epsilon.^3.*Pp.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.*r.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(temp2) - epsilon.*r.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum(sin((-1 + ms).*omega).*Sp,3) + epsilon.^2.*P.*(1 + epsilon.^2.*Pp - deltap.*epsilon.*cos(omega) + epsilon.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3));
	temp12 = -((-(BB.*d2betapardB2) + dbetapardB).*epsilon.*sum(Bsp.*cos(mb.*omega),3)) + BB.*(d2betapardrdB + d2betapardRdB.*epsilon.*(temp2));
	temp13 = RR.*(T8);
	temp17 = sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*(temp2) - sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(temp8) - (epsilon.^2.*P + r).*(-(deltap.*sin(omega)) + sin(omega).*sum(cos((-1 + ms).*omega).*Sp,3) + cos(omega).*sum(sin((-1 + ms).*omega).*Sp,3));
