	temp19 = (deltapp.*epsilon.*r.*RR.*(Tfun).*(temp3).*(epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))))./(temp1).^2 - (epsilon.^2.*Ppp.*r.*RR.*(Tfun).*cos(omega).*(temp3).*(epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))))./(temp1).^2 + (epsilon.^2.*Ppp.*r.*RR.*(Tfun).*sin(omega).*(-(epsilon.^2.*P.*sin(omega)) - r.*sin(omega) + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)).*(epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))))./(temp1).^2 - (r.*RR.*(Tfun).*(epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))).*(temp2).*(temp5))./(temp1).^2 + (RR.*(Tfun).*(epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))))./(temp1) + (epsilon.^2.*r.*RR.*t2p.*(epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))))./(temp1) - (epsilon.*r.*(Tfun).*(epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))).*(temp2))./(temp1) + (2.*r.*RR.*(Tfun).*(temp3).*(temp5))./(temp1) + (2.*r.*RR.*(Tfun).*(temp7).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3)))./(temp1) + (r.*RR.*(Tfun).*(epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))).*(temp8).*(-((1 + epsilon.^2.*Pp).*sin(omega)) + epsilon.*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3)))./(temp1).^2 - (epsilon.*r.*RR.*(Tfun).*(temp3).*(epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))).*sum(cos((-1 + ms).*omega).*Spp,3))./(temp1).^2 - (epsilon.*r.*RR.*(Tfun).*(-(epsilon.^2.*P.*sin(omega)) - r.*sin(omega) + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)).*(epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))).*sum(sin((-1 + ms).*omega).*Spp,3))./(temp1).^2;
	temp20 = r.*sin(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sum(-((-1 + ms).^2.*S.*sin((-1 + ms).*omega)),3).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.^2.*P.*sin(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) - r.*sin(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) - epsilon.^2.*P.*cos(omega).*sum(sin((-1 + ms).*omega).*Sp,3) - r.*cos(omega).*sum(sin((-1 + ms).*omega).*Sp,3) - sum(-((-1 + ms).^2.*cos((-1 + ms).*omega).*S),3).*(temp8) + epsilon.^2.*P.*cos(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3) + r.*cos(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3) + sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3));
	T1 = temp1;
	T2 = epsilon.^4.*P.^2 + r.^2 - 2.*epsilon.*r.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.^2.*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3).^2 - 2.*epsilon.*r.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3) + epsilon.^2.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3).^2 - 2.*epsilon.^2.*P.*(-r + epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) + epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3));
	T3 = (temp1).^(-2);
	T4 = 1./(temp1);
	T5 = temp17;
	T6 = (temp1).^(-3);
	T7 = temp4 - temp6 + temp9 - temp11 - temp20;
	
	T15 = 2.*(temp3).*(temp5).*(temp1) + 2.*(temp7).*(temp1).*(sin(omega) + epsilon.^2.*Pp.*sin(omega) - epsilon.*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3)) - 2.*epsilon.*(temp1).*(T8) + 2.*epsilon.^2.*(temp17).*(temp4 - temp6 + temp9 - temp11 - temp20);
	T19 = 2.*epsilon.^2.*RR.*sum(-(mb.*Bs.*sin(mb.*omega)),3).*(temp17).*(temp1) + 2.*BB.*epsilon.^2.*(-(epsilon.^2.*P.*sin(omega)) - r.*sin(omega) + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)).*(temp17).*(temp1) + BB.*RR.*(T15);
	T20 = (temp3).*(temp2) + (temp7).*(temp8);
	T23 = 2.*BB.*epsilon.^2.*RR.*(d2betapardB2.*sum(-(mb.*Bs.*sin(mb.*omega)),3) + d2betapardRdB.*(-(epsilon.^2.*P.*sin(omega))- r.*sin(omega)  + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))).*(temp17).*(temp1) - dbetapardB.*(T19);
	T29 = (temp10)./(temp1) - (temp13)./(temp1) + (epsilon.*RR.*(temp17).*(temp4 - temp6 + temp9 - temp11 - temp20))./(temp1).^2;
