	T53 = dbetapardr - (BB.*dbetapardB.*epsilon.*(Tfun).^2.*(temp2))./temp14 - temp16  + (BB.*(Tfun).*(BB.*(BB - dbetapardB.*epsilon.^2).*t2p + (Tfun).*(-(dbetapardB.*epsilon.*sum(Bsp.*cos(mb.*omega),3)) + temp16)))./((BB - dbetapardB.*epsilon.^2).^3.*RR.^2) + (epsilon.*r.^2.*(Tfun).^2.*(T29))./(q.^2.*RR.^3.*(temp1)) + (epsilon.^2.*r.^2.*(Tfun).^2.*(2.*BB.*epsilon.^2.*RR.*(d2betapardB2.*sum(-(mb.*Bs.*sin(mb.*omega)),3) + d2betapardRdB.*(-(epsilon.^2.*P.*sin(omega))- r.*sin(omega) + epsilon.*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3))).*(temp17).*(temp1) - dbetapardB.*(T19)))./(2..*BB.^2.*q.^2.*RR.^3.*(temp1).^3) + (r.*(Tfun).*(-(temp18) + q.*(temp19)))./(q.^3.*RR.^3.*(temp1));
