	T60 = deltap.*sin(omega) - sin(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - sin(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*Sp,3) - cos(omega).*sum(sin((-1 + ms).*omega).*Sp,3) + cos(omega).*sum(-((-1 + ms).*sin((-1 + ms).*omega).*Sp),3);
	jacTotal = zeros(3,nRes,nRes,Nq); % (which deriv, which equation, which profile)

