	for kp = 2:(Ns+1)
    	T10 = -((-1 + kp).*cos((-1 + kp).*omega).*1.*(temp2)) - -((-1 + kp).*1.*sin((-1 + kp).*omega)).*(temp8);
		jacTotal(1, 3 + Nb + (kp - 1), gamma, :) = mean((-(RR.*T10) + epsilon.*T20.*cos((-1 + kp).*omega).*1)./(epsilon.*RR.^2), 2);
		jacTotal(2, 3 + Nb + (kp - 1), gamma, :) = mean((-(cos((-1 + kp).*omega).*1.*(temp3)) + 1.*sin((-1 + kp).*omega).*(temp7))./(epsilon.*RR), 2);
	end

	% --- resB modes ---
	j11B = (2.*epsilon.*(Tfun).*(-(BB.^2./(BB - dbetapardB.*epsilon.^2).^2) - (epsilon.^2.*r.^2.*T2.*T3)./q.^2))./RR.^2;
	j11B_FFT = real(fft(j11B, [], 2)) / Ntheta;
	jacTotal(1,1, rowsB, :) = reshape(j11B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j12B = (2.*epsilon.*(Tfun).^2.*(-((BB.^2.*(BB - dbetapardB.*epsilon.^2 - d2betapardRdB.*epsilon.^2.*RR))./(BB - dbetapardB.*epsilon.^2).^3) - (epsilon.^2.*r.^2.*T2.*T3)./q.^2))./RR.^3;
	j12B_FFT = real(fft(j12B, [], 2)) / Ntheta;
	jacTotal(1,2, rowsB, :) = reshape(j12B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j13B = (2.*(epsilon - dbetapardB0.*epsilon.^3 + epsilon.^3.*t2).^2.*((BB.^2.*(BB - dbetapardB.*epsilon.^2 - d2betapardRdB.*epsilon.^2.*RR).*cos(omega))./(BB - dbetapardB.*epsilon.^2).^3 + (epsilon.^2.*r.^2.*T2.*T3.*cos(omega))./q.^2 - (epsilon.*r.^2.*RR.*T3.*(epsilon.^2.*P + r - epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))./q.^2 + (epsilon.*r.^2.*RR.*T2.*T6.*(1 + epsilon.^2.*Pp - deltap.*epsilon.*cos(omega) + epsilon.*cos(omega).*sum(cos((-1 + ms).*omega).*Sp,3) - epsilon.*sin(omega).*sum(sin((-1 + ms).*omega).*Sp,3)))./q.^2))./RR.^3;
	j13B_FFT = real(fft(j13B, [], 2)) / Ntheta;
	jacTotal(1,3, rowsB, :) = reshape(j13B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j22B = (-2.*epsilon.^2.*r.^2.*(Tfun).^2.*T2.*T6.*(temp3))./(q.^2.*RR.^2);
	j22B_FFT = real(fft(j22B, [], 2)) / Ntheta;
	jacTotal(2,2, rowsB, :) = reshape(j22B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	j23B = (2.*epsilon.^3.*r.^2.*(Tfun).^2.*T2.*T6.*(epsilon.^2.*P + r - epsilon.*cos(omega).*sum((-1 + ms).*cos((-1 + ms).*omega).*S,3) - epsilon.*sin(omega).*sum(-((-1 + ms).*S.*sin((-1 + ms).*omega)),3)))./(q.^2.*RR.^2);
	j23B_FFT = real(fft(j23B, [], 2)) / Ntheta;
	jacTotal(2,3, rowsB, :) = reshape(j23B_FFT(:, mB+1).', [1,1,nmB, Nq]);

	% derivatives wrt B_l (bundle)
	for lp = 0:Nb-1
		j13lpB = 2.*BB.*(1 - (BB.*(-1 + d2betapardB2.*epsilon.^2).*(Tfun).^2)./((BB - dbetapardB.*epsilon.^2).^3.*RR.^2) - (Tfun).^2./((BB - dbetapardB.*epsilon.^2).^2.*RR.^2)).*cos(lp.*omega);
		j13lpB_FFT = real(fft(j13lpB, [], 2)) / Ntheta;
		jacTotal(1, 3+lp+1, rowsB, :) = reshape(j13lpB_FFT(:, mB+1).', [1,1,nmB, Nq]);
	end

	% derivatives wrt S_k (bundle), k=2..Ns+1
	for kp = 2:(Ns+1)
        T9 = cos((-1 + kp).*omega).*1.*(temp3) - 1.*sin((-1 + kp).*omega).*(temp7);
	    T10 = -((-1 + kp).*cos((-1 + kp).*omega).*1.*(temp2)) - -((-1 + kp).*1.*sin((-1 + kp).*omega)).*(temp8);
        T47 = -2.*((-1 + kp).*cos((-1 + kp).*omega).*1.*(temp3) + -((-1 + kp).*1.*sin((-1 + kp).*omega)).*(temp7));
        j13kpB = (epsilon.*(Tfun).^2.*((2.*BB.^2.*(BB - dbetapardB.*epsilon.^2 - d2betapardRdB.*epsilon.^2.*RR).*cos((-1 + kp).*omega).*1)./(BB - dbetapardB.*epsilon.^2).^3 + (epsilon.*r.^2.*(-(RR.*T3.*T47) + 2.*RR.*T10.*T2.*T6 + 2.*epsilon.*T2.*T3.*cos((-1 + kp).*omega).*1))./q.^2))./RR.^3;
		j13kpB_FFT = real(fft(j13kpB, [], 2)) / Ntheta;
		jacTotal(1, 3 + Nb + (kp - 1), rowsB, :) = reshape(j13kpB_FFT(:, mB+1).', [1,1,nmB, Nq]);
		j23kpB = (2.*epsilon.^2.*r.^2.*(Tfun).^2.*T2.*T6.*T9)./(q.^2.*RR.^2);
		j23kpB_FFT = real(fft(j23kpB, [], 2)) / Ntheta;
		jacTotal(2, 3 + Nb + (kp - 1), rowsB, :) = reshape(j23kpB_FFT(:, mB+1).', [1,1,nmB, Nq]);
	end
	%% Construct J
    %totalDofs = dof_count * (3 + Nb) + (dof_count-1) *Ns;
    totalDofs = dof_count * (2 + Nb) + (dof_count-1) *(Ns+1);
    nCols = (3+ Nb + Ns)^2 * Nq;
    % precomputed: M_extended (totalDofs x nCols), P_templates{d} with fields i,j,v_template
    J = spalloc(totalDofs, totalDofs, 1 * nnz(M_extended));  % or a tighter nnz estimate

    for d = 1:3
        % Extract jacobian block and flatten in the SAME order P_templates was built.
        jac_d = squeeze(jacTotal(d,:,:,:));    % size: [nProfiles, nProfiles, Nq] (alpha,gamma,q)
        % permute to [q, gamma, alpha] then linearize -> ordering matches P_templates{d}.i
        jacTotal_flat = reshape(permute(jac_d, [3, 1, 2]), [], 1);   % length == nCols

        % Row-scale P template by jac values (this gives diag(jac)*P_extended)
        vP_scaled = P_templates{d}.v_template .* jacTotal_flat(P_templates{d}.i);

        % Create sparse scaled-P and accumulate J via M_extended * P_scaled
        P_scaled = sparse(P_templates{d}.i, P_templates{d}.j, vP_scaled, nCols, totalDofs);
        J = J + M_extended * P_scaled;
    end
end
